#include "profiles/whj2.hpp"
#include "story.hpp"
#include <iostream>
int main(int argc,char**argv){try{if(argc<2)throw std::runtime_error("usage: story-probe GAME [choice bits]");qlie::Assets assets(argv[1],whj2::profile::archives);whj2::Story s(assets,whj2::profile::story);s.start();unsigned decisions=0,messages=0,events=0;std::string bits=argc>2?argv[2]:"000000";for(;events<2000000;events++){auto e=s.next();if(e.type=="choice"){unsigned c=decisions<bits.size()?unsigned(bits[decisions]-48):0;std::cout<<"choice "<<decisions<<" "<<e.file<<":"<<e.line<<" => "<<c<<"\n";s.choose(c);decisions++;}if(e.type=="text")messages++;if(events%211==0){auto b=s.save();whj2::Story restored(assets,whj2::profile::story);restored.restore(b);auto a=s.next(),z=restored.next();if(a.type!=z.type||a.value!=z.value||a.file!=z.file||a.line!=z.line)throw std::runtime_error("Save continuation mismatch");s.restore(b);}if(e.type=="finish"||e.type=="finished")break;}if(events==2000000)throw std::runtime_error("No ending reached");std::cout<<"PASS story events="<<events<<" text="<<messages<<" decisions="<<decisions<<" ops="<<s.operations<<" route="<<s.state.vars["game_routeflag[0]"]<<"\n";for(auto&v:s.state.vars)if(v.first.find("clearflag")!=v.first.npos)std::cout<<v.first<<"="<<v.second<<"\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<"\n";return 1;}}
